//! 🧫️ Independent serde fields survive one-item original Record parsing and paid cancellation.
use super::*;
use semio_framework_dsl_record::{BorrowedFieldSpec,RecordLayout,FieldSpec,RecordSpec};
use semio_framework_value::retirement::RetireOwned;
static FIELDS:[BorrowedFieldSpec;2]=[BorrowedFieldSpec::new(0,"text",BorrowedShape::Text),BorrowedFieldSpec::new(1,"items",BorrowedShape::List(||BorrowedShape::Text))];
fn spec()->BorrowedRecordSpec{BorrowedRecordSpec{keyword:None,layout:RecordLayout::Inline,fields:&FIELDS}}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant()->RetainedCloneGrant{let f=fixture();let f=&f["turn"];RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize}}
fn source()->(Vec<u8>,RecordValue){let f=fixture();let text:String=serde_json::from_value(f["text"].clone()).unwrap();let items:Vec<String>=serde_json::from_value(f["items"].clone()).unwrap();let mut expected=RecordValue::default();expected.fields.insert(0,FieldValue::Text(text));expected.fields.insert(1,FieldValue::List(items.into_iter().map(FieldValue::Text).collect()));let owned=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(0,"text",semio_framework_dsl_record::Shape::Text),FieldSpec::new(1,"items",semio_framework_dsl_record::Shape::List(Box::new(semio_framework_dsl_record::Shape::Text)))]);let source=semio_framework_pack_record::encode_record_body(&owned,&expected,&Default::default()).unwrap();(source,expected)}
#[test]
fn original_record_receiving_one_item_retains_source_native_and_serde_output(){
 let(source,expected)=source();let grant=grant();let mut native_callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut native_callback);let(mut receiving,admitted)=RetainedRecordReceiving::admit(&source,(0,source.len()),spec(),PackLimits::default(),grant).unwrap().unwrap();assert_eq!(admitted.copied_items,1);let mut births=0;let mut releases=0;let mut turns=0;
 while !receiving.is_ready(){assert!(turns<10000);let demand=receiving.demands(&source).unwrap();let mut denied=grant;denied.maximum_items=0;assert_eq!(receiving.step(&source,&mut native,denied).unwrap(),Default::default());let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||receiving.step(&source,&mut native,grant));let progress=result.unwrap();assert_eq!(progress.copied_items,1);assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.retained_capacity_bytes<=demand.capacity_bytes);births+=born;releases+=released;turns+=1;}
 let mut output=None;let progress=receiving.take_into(&mut output,grant).unwrap();assert_eq!(progress.copied_items,1);assert_eq!(output.as_ref(),Some(&expected));let output=output.take().unwrap();let mut output=ControlledRetirement::new(output).ok().unwrap();while !output.terminal_is_empty(){let(step,born,released)=semio_framework_trace_memory_testing::observe_backing(||output.step(grant));let progress=step.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=released;}
 while !receiving.terminal_is_empty(){let(step,born,released)=semio_framework_trace_memory_testing::observe_backing(||receiving.close_step(grant));let progress=step.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=released;}assert_eq!(births,releases);
}
#[test]
fn original_record_receiving_partial_original_owner_closes_under_independent_release(){
 let(source,_)=source();let grant=grant();let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut observer);let(mut receiving,_)=RetainedRecordReceiving::admit(&source,(0,source.len()),spec(),PackLimits::default(),grant).unwrap().unwrap();for _ in 0..50{receiving.step(&source,&mut native,grant).unwrap();}let mut original=ControlledRetirement::new(receiving).ok().unwrap();let mut denied=grant;denied.maximum_release_bytes=0;for _ in 0..1000{let progress=original.step(denied).unwrap().progress();assert_eq!(progress.released_bytes,0);if progress==Default::default(){break}}assert!(!original.terminal_is_empty());for _ in 0..10000{if original.terminal_is_empty(){break}original.step(grant).unwrap();}assert!(original.terminal_is_empty());
}
fn nested_borrowed()->BorrowedRecordSpec{static FIELDS:[BorrowedFieldSpec;1]=[BorrowedFieldSpec::new(0,"text",BorrowedShape::Text)];BorrowedRecordSpec{keyword:Some("node"),layout:RecordLayout::Inline,fields:&FIELDS}}
fn nested_owned()->RecordSpec{RecordSpec::new(Some("node"),RecordLayout::Inline,vec![FieldSpec::new(0,"text",semio_framework_dsl_record::Shape::Text)])}
fn producer()->semio_framework_dsl_record::RecordSpecProducer{semio_framework_dsl_record::RecordSpecProducer{ordinary:nested_owned,decoding:|_|Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"fixture only invokes ordinary producer")),encoding:|_|Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"fixture only invokes ordinary producer"))}}
fn nested(text:&str)->RecordValue{let mut record=RecordValue::default();record.fields.insert(0,FieldValue::Text(text.to_owned()));record}
#[test]
fn original_record_receiving_recursive_containers_and_wire_preserve_independent_json_fields(){
 use semio_framework_dsl_record::{Shape,WireValue,WireNode,WireEdgeLabel};
 static FIELDS:[BorrowedFieldSpec;6]=[BorrowedFieldSpec::new(0,"block",BorrowedShape::Block(||BorrowedShape::Record(nested_borrowed))),BorrowedFieldSpec::new(1,"statements",BorrowedShape::Statements(&[("node",nested_borrowed)])),BorrowedFieldSpec::new(2,"dynamic",BorrowedShape::Value),BorrowedFieldSpec::new(3,"wire",BorrowedShape::Wire),BorrowedFieldSpec::new(4,"unsigned",BorrowedShape::List(||BorrowedShape::UInt)),BorrowedFieldSpec::new(5,"map",BorrowedShape::Map(||BorrowedShape::Text))];
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🪆️containers.json")).unwrap();let mut expected=RecordValue::default();expected.fields.insert(0,FieldValue::Block(Box::new(FieldValue::Record(nested(f["nested"].as_str().unwrap())))));expected.fields.insert(1,FieldValue::Statements(f["statements"].as_array().unwrap().iter().map(|text|("node".to_owned(),nested(text.as_str().unwrap()))).collect()));expected.fields.insert(2,FieldValue::Value(DslValue::from(&f["dynamic"])));let w=&f["wire"];expected.fields.insert(3,FieldValue::Wire(WireValue{from:WireNode{id:w["from"].as_str().unwrap().into(),kind:Some(w["kind"].as_str().unwrap().into()),port:Some(w["fromPort"].as_str().unwrap().into())},edge:Some((w["directed"].as_bool().unwrap(),WireNode{id:w["to"].as_str().unwrap().into(),kind:Some(w["kind"].as_str().unwrap().into()),port:Some(w["toPort"].as_str().unwrap().into())})),edge_label:WireEdgeLabel{id:Some(w["label"].as_str().unwrap().into()),kind:Some(w["labelKind"].as_str().unwrap().into())},properties:DslValue::from(&f["dynamic"])}));expected.fields.insert(4,FieldValue::List(serde_json::from_value::<Vec<u64>>(f["unsigned"].clone()).unwrap().into_iter().map(FieldValue::UInt).collect()));expected.fields.insert(5,FieldValue::Map(serde_json::from_value::<Vec<(String,String)>>(f["map"].clone()).unwrap().into_iter().map(|(key,value)|(key,FieldValue::Text(value))).collect()));
 let owned=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(0,"block",Shape::Block(Box::new(Shape::Record(producer())))),FieldSpec::new(1,"statements",Shape::Statements(vec![("node".into(),producer())])),FieldSpec::new(2,"dynamic",Shape::Value),FieldSpec::new(3,"wire",Shape::Wire),FieldSpec::new(4,"unsigned",Shape::List(Box::new(Shape::UInt))),FieldSpec::new(5,"map",Shape::Map(Box::new(Shape::Text)))]);let source=semio_framework_pack_record::encode_record_body(&owned,&expected,&Default::default()).unwrap();let grant=grant();let(mut receiving,_)=RetainedRecordReceiving::admit(&source,(0,source.len()),BorrowedRecordSpec{keyword:None,layout:RecordLayout::Inline,fields:&FIELDS},PackLimits::default(),grant).unwrap().unwrap();let mut callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut callback);let mut turns=0;while !receiving.is_ready(){assert!(turns<100000);let progress=receiving.step(&source,&mut native,grant).unwrap();assert_eq!(progress.copied_items,1);assert!(progress.fits(grant));turns+=1;}let mut output=None;receiving.take_into(&mut output,grant).unwrap();assert_eq!(output.as_ref(),Some(&expected));while !receiving.terminal_is_empty(){receiving.close_step(grant).unwrap();}let mut output=ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !output.terminal_is_empty(){output.step(grant).unwrap();}
}

fn table_borrowed()->BorrowedRecordSpec{static FIELDS:[BorrowedFieldSpec;7]=[BorrowedFieldSpec::new(0,"label",BorrowedShape::Text),BorrowedFieldSpec::new(1,"enabled",BorrowedShape::Bool),BorrowedFieldSpec::new(2,"amount",BorrowedShape::Int),BorrowedFieldSpec::new(3,"count",BorrowedShape::UInt),BorrowedFieldSpec::new(4,"ratio",BorrowedShape::Float),BorrowedFieldSpec::new(5,"choice",BorrowedShape::Enum(&[("zero",0),("one",1),("two",2)])),BorrowedFieldSpec::new(6,"child",BorrowedShape::Record(nested_borrowed))];BorrowedRecordSpec{keyword:None,layout:RecordLayout::Inline,fields:&FIELDS}}
fn table_owned()->RecordSpec{use semio_framework_dsl_record::Shape;RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(0,"label",Shape::Text),FieldSpec::new(1,"enabled",Shape::Bool),FieldSpec::new(2,"amount",Shape::Int),FieldSpec::new(3,"count",Shape::UInt),FieldSpec::new(4,"ratio",Shape::Float),FieldSpec::new(5,"choice",Shape::Enum(vec![("zero".into(),0),("one".into(),1),("two".into(),2)])),FieldSpec::new(6,"child",Shape::Record(producer()))])}
#[test]
fn original_record_receiving_columnar_sparse_table_preserves_independent_rows_and_receipts(){
 use semio_framework_dsl_record::{Shape,RecordSpecProducer};let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📊️table.json")).unwrap();let rows=f["rows"].as_array().unwrap().iter().map(|row|{let mut record=RecordValue::default();for(id,value)in row.as_array().unwrap().iter().enumerate(){let value=if value.is_null(){FieldValue::Absent}else{match id{0=>FieldValue::Text(value.as_str().unwrap().into()),1=>FieldValue::Bool(value.as_bool().unwrap()),2=>FieldValue::Int(value.as_i64().unwrap()),3=>FieldValue::UInt(value.as_u64().unwrap()),4=>FieldValue::Float(value.as_f64().unwrap()),5=>FieldValue::Enum(value.as_u64().unwrap()as u32),6=>FieldValue::Record(nested(value.as_str().unwrap())),_=>unreachable!()}};record.fields.insert(id as u16,value);}FieldValue::Record(record)}).collect();let mut expected=RecordValue::default();expected.fields.insert(0,FieldValue::List(rows));let producer=RecordSpecProducer{ordinary:table_owned,decoding:|_|Err(invalid("fixture uses ordinary metadata")),encoding:|_|Err(invalid("fixture uses ordinary metadata"))};let spec=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(0,"rows",Shape::Table(producer))]);let source=semio_framework_pack_record::encode_record_body(&spec,&expected,&Default::default()).unwrap();static FIELDS:[BorrowedFieldSpec;1]=[BorrowedFieldSpec::new(0,"rows",BorrowedShape::Table(table_borrowed))];let grant=grant();let(mut receiving,_)=RetainedRecordReceiving::admit(&source,(0,source.len()),BorrowedRecordSpec{keyword:None,layout:RecordLayout::Inline,fields:&FIELDS},PackLimits::default(),grant).unwrap().unwrap();let mut callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut callback);let mut turns=0;let mut births=0;let mut releases=0;while !receiving.is_ready(){assert!(turns<100000);let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||receiving.step(&source,&mut native,grant));let progress=result.unwrap();assert_eq!(progress.copied_items,1);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.fits(grant));births+=born;releases+=released;turns+=1;}let mut output=None;receiving.take_into(&mut output,grant).unwrap();assert_eq!(output.as_ref(),Some(&expected));while !receiving.terminal_is_empty(){let(step,born,released)=semio_framework_trace_memory_testing::observe_backing(||receiving.close_step(grant));let progress=step.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=released;}let mut output=ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !output.terminal_is_empty(){let(step,born,released)=semio_framework_trace_memory_testing::observe_backing(||output.step(grant));let progress=step.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=released;}assert_eq!(births,releases);
}
